VALUES (36046, 'tt0159208', NULL, 'City Hunter', 'シティーハンター', 'tv', 1987, 'https://image.tmdb.org/t/p/w500/4BA0FDKiJD0N4ljYhlwOVjQKszR.jpg', 'https://image.tmdb.org/t/p/original/nyyZ7co7wypIqSwkgoBBMe9jDK4.jpg', 'Ryo Saeba works the streets of Tokyo as the City Hunter. He''s a "sweeper" and with his sidekick Kaori Makimura, he keeps the city clean. People hire the City Hunter to solve their dangerous problems, which he does with a Colt Python. When Ryo''s not working on a case, he''s working on getting the ladies, and Kaori must keep him in check with her trusty 10 kg hammer.', NULL, NULL, 32.3096, 7.8, 0, 9.05, '2026-11-27 20:26:40', '2026-11-27 20:26:40')
