VALUES (20450, 'tt0813971', NULL, 'Witchblade', 'ウィッチブレイド', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/rURfkcQ0OjiboUyzf8OnEruBouE.jpg', 'https://image.tmdb.org/t/p/original/5oxRm8elqTRjeu7WRjdtPv8VnDZ.jpg', 'Masane Amaha and her daughter Rihoko are on the run from a government child welfare agency that wants to take Rihoko away from her mother. They are caught and Rihoko is taken away. Meanwhile, Masane is attacked by an advanced weapon that can disguise itself as a human being. When faced with the danger, a strange light emits from her wrist and she transforms into a powerful being. She becomes involved in a power struggle between powerful organizations, with her at the center of their attention because she holds the greatest power of them all, the legendary Witchblade.', NULL, NULL, 12.3283, 7.8, 0, 8.51, '2026-11-27 20:26:40', '2026-11-27 20:26:40')
