VALUES (60741, 'tt3696720', NULL, 'Ascension', 'Ascension', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/lBfc0PXqQkRYTmIyN2fmbhy365e.jpg', 'https://image.tmdb.org/t/p/original/j9LbgzMsVTnC817Pevpl3igRG5.jpg', 'In 1963, the U.S. government launched a covert space mission sending hundreds of men, women and children on a century-long voyage aboard the starship Ascension to populate a new world. Nearly 50 years into the journey, as they approach the point of no return, a mysterious murder of a young woman causes the ship’s population to question the true nature of their mission.', NULL, NULL, 5.7335, 6.6, 0, 1.03, '2026-11-27 20:26:40', '2026-11-27 20:26:40')
