VALUES (117239, 'tt0042621', NULL, 'Juliette, or Key of Dreams', 'Juliette ou La Clef des songes', 'movie', 1951, 'https://image.tmdb.org/t/p/w500/px3iQgtKflMkSV6XlKInK3wqiiX.jpg', 'https://image.tmdb.org/t/p/original/1DRbBWnWVIRI1VnYdrgxxpOULSd.jpg', 'Michel has stolen from his employer, Mr Bellanger, for the love of Juliette. He is now in jail. One night, while sleeping in his cell, he wakes up all of a sudden, the gates open and he finds himself in a strange village where all the inhabitants have lost their memory. There, meets Juliette again who seems to agree to marry a powerful man, who might well be Bluebeard...', NULL, NULL, 1.0881, 7.0, 0, 1.02, '2026-11-27 20:26:40', '2026-11-27 20:26:40')
