VALUES (113947, 'tt1866249', NULL, 'The Sessions', 'The Sessions', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/57o1DBc5DfJXVc8wArAblSbZ8sD.jpg', 'https://image.tmdb.org/t/p/original/6P6YdvJsAZlUZKipA86rbfjfKzD.jpg', 'Though a childhood bout with polio left him dependent on an iron lung, Mark O''Brien maintains a career as a journalist and poet. A writing assignment dealing with sex and the disabled piques Mark''s curiosity, and he decides to investigate the possibility of experiencing sex himself. When his overtures toward a caregiver scare her away, he books an appointment with sex surrogate Cheryl Cohen-Greene to lose his virginity.', NULL, NULL, 2.7845, 6.87, 0, 10.01, '2026-11-27 20:26:40', '2026-11-27 20:26:40')
