VALUES (14784, 'tt0460791', NULL, 'The Fall', 'The Fall', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/ez7xavvDr5yDz4sSvI55xDp0BoU.jpg', 'https://image.tmdb.org/t/p/original/vNrXoT45xscHY6AN4IGf44vHxVJ.jpg', 'In a hospital on the outskirts of 1920s Los Angeles, an injured stuntman begins to tell a fellow patient, a little girl with a broken arm, a fantastic story about 5 mythical heroes. Thanks to his fractured state of mind and her vivid imagination, the line between fiction and reality starts to blur as the tale advances.', NULL, NULL, 6.6961, 7.621, 0, 1.35647307692307691e+02, '2026-07-15 12:01:52', '2026-11-27 20:26:40')
