VALUES (235, 'tt0092005', NULL, 'Stand by Me', 'Stand by Me', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/vz0w9BSehcqjDcJOjRaCk7fgJe7.jpg', 'https://image.tmdb.org/t/p/original/yjGllQUm28R4X9xD9T5xMszirgw.jpg', 'After learning that a boy their age has been accidentally killed near their rural homes, four boys decide to go see the body. Gordie, Vern, Chris, and Teddy encounter a mean junk man and a marsh full of leeches, but they also learn more about one another and their very different home lives. Just a lark at first, the boys'' adventure evolves into a defining event in their lives.', NULL, NULL, 8.5669, 7.834, 0, 8.38482278481012741e+01, '2026-07-15 12:01:52', '2026-11-27 20:26:40')
