VALUES (65086, 'tt1596365', NULL, 'The Woman in Black', 'The Woman in Black', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/peKkO5lYyyZ7flxeFuXoZPXArXo.jpg', 'https://image.tmdb.org/t/p/original/jJ3yFKs6xeVGxtmm7GXZYQ3XAvz.jpg', 'The story follows a young lawyer, Arthur Kipps, who is ordered to travel to a remote village and sort out a recently deceased client’s papers. As he works alone in the client’s isolated house, Kipps begins to uncover tragic secrets, his unease growing when he glimpses a mysterious woman dressed only in black. Receiving only silence from the locals, Kipps is forced to uncover the true identity of the Woman in Black on his own, leading to a desperate race against time when he discovers her true identity.', NULL, NULL, 4.4358, 6.151, 0, 4.86826666666666696e+01, '2026-07-15 12:01:52', '2026-11-27 20:26:40')
