VALUES (13198, 'tt0477139', NULL, 'Wristcutters: A Love Story', 'Wristcutters: A Love Story', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/qModiIR60IMLP28ruGZluQOtsOj.jpg', 'https://image.tmdb.org/t/p/original/wDLgGI6Rswo30YkWoM6TGq0VWVy.jpg', 'Zia, distraught over breaking up with his girlfriend, decides to end it all. Unfortunately, he discovers that there is no real ending, only a run-down afterlife that is strikingly similar to his old one, just a bit worse. Discovering that his ex-girlfriend has also "offed" herself, he sets out on a road trip to find her.', NULL, NULL, 2.8504, 7.0, 0, 6.20042857142857144e+01, '2026-07-15 12:01:52', '2026-11-27 20:26:40')
