VALUES (756999, 'tt7144666', NULL, 'The Black Phone', 'The Black Phone', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/p9ZUzCyy9wRTDuuQexkQ78R2BgF.jpg', 'https://image.tmdb.org/t/p/original/AfvIjhDu9p64jKcmohS4hsPG95Q.jpg', 'Finney Blake, a shy but clever 13-year-old boy, is abducted by a sadistic killer and trapped in a soundproof basement where screaming is of little use. When a disconnected phone on the wall begins to ring, Finney discovers that he can hear the voices of the killer’s previous victims. And they are dead set on making sure that what happened to them doesn’t happen to Finney.', NULL, NULL, 6.8996, 7.5, 0, 2.17383333333333332e+01, '2026-07-15 12:01:52', '2026-11-27 20:26:40')
