VALUES (80, 'tt0381681', NULL, 'Before Sunset', 'Before Sunset', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/gycdE1ARByGQcK4fYR2mgpU6OO.jpg', 'https://image.tmdb.org/t/p/original/tcZi0LQc5iu2u6i5aOWyj9NBBvl.jpg', 'Nine years later, Jesse travels across Europe giving readings from a book he wrote about the night he spent in Vienna with Celine. After his reading in Paris, Celine finds him, and they spend part of the day together before Jesse has to again leave for a flight. They are both in relationships now, and Jesse has a son, but as their strong feelings for each other start to return, both confess a longing for more.', NULL, NULL, 6.3006, 7.813, 0, 2.7810416666666665e+01, '2026-07-15 12:01:52', '2026-11-27 20:26:40')
