VALUES (16220, 'tt0076929', NULL, 'Wizards', 'Wizards', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/16DeicZZ209y9w5gnqpEvVskMca.jpg', 'https://image.tmdb.org/t/p/original/12GtHVMtsq9jtialSIgm5qVZfJa.jpg', 'After the death of his mother, evil mutant wizard Blackwolf discovers long-lost military technologies. Full of ego and ambition, Blackwolf claims his mother''s throne, assembles an army, and sets out to brainwash and conquer Earth. Meanwhile, Blackwolf''s gentle twin brother, the bearded sage Avatar, calls upon his own magical abilities to foil Blackwolf''s plans for world domination — even if it means eliminating his own flesh and blood.', NULL, NULL, 1.7107, 6.2, 0, 4.68141860465116295e+01, '2026-07-15 12:01:52', '2026-11-27 20:26:40')
