VALUES (250574, 'tt2428170', NULL, 'Creep', 'Creep', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/qn53D574tT0YRyLgirEFHQwGUXw.jpg', 'https://image.tmdb.org/t/p/original/AvrGwToWkP6fp13lzpxsyzoq9JH.jpg', 'Looking for work, Aaron comes across a cryptic online ad: "$1,000 for the day. Filming service. Discretion is appreciated." Low on cash and full of naiveté, he decides to go for it. He drives to a cabin in a remote mountain town where he meets Josef, his cinematic subject for the day. Josef is sincere and the project seems heartfelt, so Aaron begins to film. But as the day goes on, it becomes clear that Josef is not who he says, and his intentions are not at all pure.', NULL, NULL, 3.7498, 6.409, 0, 4.27771794871794881e+01, '2026-07-20 04:02:06', '2026-11-27 20:26:40')
