VALUES (137113, 'tt1631867', NULL, 'Edge of Tomorrow', 'Edge of Tomorrow', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg', 'https://image.tmdb.org/t/p/original/4V1yIoAKPMRQwGBaSses8Bp2nsi.jpg', 'Major Bill Cage is an officer who has never seen a day of combat when he is unceremoniously demoted and dropped into combat. Cage is killed within minutes, managing to take an alpha alien down with him. He awakens back at the beginning of the same day and is forced to fight and die again... and again - as physical contact with the alien has thrown him into a time loop.', NULL, NULL, 27.0346, 7.644, 0, 2.72926086956521736e+01, '2026-07-20 04:02:06', '2026-11-27 20:26:40')
