VALUES (26198, 'tt0085780', NULL, 'The Keep', 'The Keep', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/yd9wU3oajNxwaFHQ02rtTBuSFJD.jpg', 'https://image.tmdb.org/t/p/original/yqDKFfyMnhmiXJgLHYeykU0iKqC.jpg', 'Set during World War II, a German army garrison is sent to guard a mountain pass in a village in Romania''s Carpathian mountains and sets up barracks in an ancient stone fortress. Two of the soldiers unwittingly release a mysterious entity that kills or corrupts those within its influence, drawing the attention of a Gestapo commander, a Jewish scholar, and a mysterious traveller.', NULL, NULL, 2.8371, 5.643, 0, 2.1405555555555555e+01, '2026-07-20 04:02:06', '2026-11-27 20:26:40')
