VALUES (253, 'tt0060028', NULL, 'Star Trek', 'Star Trek', 'tv', 1966, 'https://image.tmdb.org/t/p/w500/f2wbC7fxiOJqzTb6HPr4N6bsjLF.jpg', 'https://image.tmdb.org/t/p/original/ywK4VrR7vL56mDGXDLMtFypwqA8.jpg', 'Space. The Final Frontier. The U.S.S. Enterprise embarks on a five year mission to explore the galaxy. The Enterprise is under the command of Captain James T. Kirk with First Officer Mr. Spock, from the planet Vulcan. With a determined crew, the Enterprise encounters Klingons, Romulans, time paradoxes, tribbles and genetic supermen led by Khan Noonian Singh. Their mission is to explore strange new worlds, to seek new life and new civilizations, and to boldly go where no man has gone before.', NULL, NULL, 72.2352, 7.982, 0, 10.3825, '2026-07-20 04:02:06', '2026-11-27 20:26:40')
