VALUES (27583, 'tt1234654', NULL, 'Greenberg', 'Greenberg', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/jAsN4vPpycVxC89QlA6NYBXRuK7.jpg', 'https://image.tmdb.org/t/p/original/yatLdOw4i5roDD2fgd5jtEx0gs7.jpg', 'Roger Greenberg, a failed musician now making a living as a carpenter in New York, returns to Los Angeles to house-sit for his brother. He''s stranded there—since he doesn''t drive—until his brother''s assistant, Florence, comes to his rescue. She''s as much a lost soul as he is, and the pair form a significant connection—giving Roger a much-needed reason to be happy.', NULL, NULL, 3.1916, 5.888, 0, 3.01333333333333319e+00, '2026-07-31 03:33:23', '2026-11-27 20:26:40')
