VALUES (687163, 'tt12042730', NULL, 'Project Hail Mary', 'Project Hail Mary', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/iOb2fjXLbpJgyQXe46n1WtGCnaa.jpg', 'https://image.tmdb.org/t/p/original/2I1OFQJ0L9T0dpU6FobKFWV2PxX.jpg', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', NULL, NULL, 108.993, 8.6, 0, 2.99610714285714294e+01, '2026-07-31 03:33:23', '2026-11-27 20:26:40')
