VALUES (NULL, NULL, 26472, 'Disco Elysium', 'Disco Elysium', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1sfj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4pd7.jpg', 'Disco Elysium is a role-playing game developed and published by ZA/UM. It is set in the fictional city of Revachol, where players assume the role of an amnesic detective investigating a murder. The game emphasizes dialogue and skill-based choices, with character attributes represented by internal voices that influence decisions and interactions. Its narrative explores themes of politics, philosophy, and personal identity, and it is known for its unconventional gameplay and deep storytelling.', 'https://www.igdb.com/games/disco-elysium', '["PC (Microsoft Windows)", "Mac"]', NULL, 9.1, 0, 6.10666666666666646e+00, '2026-07-31 03:33:23', '2026-11-27 20:26:40')
