VALUES (21453, 'tt0098692', NULL, 'Wicked City', '妖獣都市', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/aFtLwGv6pcqO72M1v5iQYZOCkZ5.jpg', 'https://image.tmdb.org/t/p/original/rmhhTF2fr8w6iNh8KHNi6EqWLZv.jpg', 'A peace treaty between the Earth and the Black World, a parallel universe of demons, is coming to an end. Two cops, Taki, a human male, and Maki, a female demon, are assigned to protect a diplomat who will help secure another treaty. A radical group of demons from the Black World are out to assassinate the diplomat and prevent the treaty; only the bond that forms between the two cops can save the Earth from destruction.', NULL, NULL, 4.1291, 6.703, 0, 11.988, '2026-08-05 03:13:48', '2026-11-27 20:26:40')
