VALUES (332, 'tt0141369', NULL, 'Inspector Gadget', 'Inspector Gadget', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/dDcsv1Lql5aM6H4JYfDHjBAXKgT.jpg', 'https://image.tmdb.org/t/p/original/7OsGo8yVkTgD1ZJMBi9M8GP5aes.jpg', 'John Brown is a bumbling but well-intentioned security guard who is badly injured in an explosion planned by an evil mastermind. He is taken to a laboratory, where Brenda, a leading robotics surgeon, replaces his damaged limbs with state-of-the-art gadgets and tools. Named "Inspector Gadget" by the press, John -- along with his niece, Penny, and her trusty dog, Brain -- uses his new powers to discover who was behind the explosion.', NULL, NULL, 4.5185, 4.534, 0, 5.92666666666666586e+00, '2026-08-06 03:21:20', '2026-11-27 20:26:40')
