VALUES (106431, 'tt10623646', NULL, 'Paper Girls', 'Paper Girls', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/6eaySyOW29li0CgXHqy7pgb0IUT.jpg', 'https://image.tmdb.org/t/p/original/otyDmwl75oagrC01LpVeegUknuP.jpg', 'It''s the day after Halloween in 1988 when four young friends accidentally stumble into an intergalactic battle and find themselves inexplicably transported to the year 2019. When they come face-to-face with their adult selves, each girl discovers her own strengths as together they try to find a way back to the past while saving the world of the future.', NULL, NULL, 5.4233, 7.275, 0, 2.015, '2026-08-11 02:46:38', '2026-11-27 20:26:40')
