VALUES (97860, 'tt12057106', NULL, 'Tower of God', '神之塔 -Tower of God-', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/9QXO4C0AwAuBa15nuDLZU2MyktB.jpg', 'https://image.tmdb.org/t/p/original/gcvJgJScIt0a5sRt8uLIkGM9IhI.jpg', 'Reach the top, and everything will be yours. At the top of the tower exists everything in this world, and all of it can be yours. You can become a god. This is the story of the beginning and the end of Rachel, the girl who climbed the tower so she could see the stars, and Bam, the boy who needed nothing but her.', NULL, NULL, 33.4616, 8.099, 0, 6.26, '2026-08-17 16:08:12', '2026-11-27 20:26:40')
