VALUES (84287, 'tt1966604', NULL, 'The Imposter', 'The Imposter', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/yMaHhVkyFL4U1jJkg9SZKo80T9w.jpg', 'https://image.tmdb.org/t/p/original/gwxItUSR8qvaKlNqsQCRVNNZAAF.jpg', 'In 1994, a 13-year-old boy disappeared without a trace from his home in San Antonio, Texas. Three-and-a-half years later, he is found alive in a village in southern Spain with a horrifying story of kidnap and torture. His family is overjoyed to bring him home. But all is not quite as it seems.', NULL, NULL, 2.1901, 7.289, 0, 5.275, '2026-08-17 16:08:12', '2026-11-27 20:26:40')
