VALUES (631842, 'tt8272064', NULL, 'Knock at the Cabin', 'Knock at the Cabin', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/dm06L9pxDOL9jNSK4Cb6y139rrG.jpg', 'https://image.tmdb.org/t/p/original/sANUefL2v8VI6fSfK3gWAG3XBt4.jpg', 'While vacationing at a remote cabin, a young girl and her two fathers are taken hostage by four armed strangers who demand that the family make an unthinkable choice to avert the apocalypse. With limited access to the outside world, the family must decide what they believe before all is lost.', NULL, NULL, 6.2677, 6.235, 0, 9.69833333333333413e+00, '2026-08-19 01:49:52', '2026-11-27 20:26:40')
