VALUES (342588, 'tt4235644', NULL, 'The Empire of Corpses', '屍者の帝国', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/gtfQzn3lRnJ2P3CcE8yxOtXPHTC.jpg', 'https://image.tmdb.org/t/p/original/Agt0eZRu9N7W17FJDNMOqYlqNDx.jpg', 'The story takes place in 19th century Europe, and revolves around John Watson. He is scouted by the government to become a secret agent. However, Watson lives in a world where "Frankensteins"—human corpses that are re-purposed with a false soul in order to use them as laborers—are used to improve industrial development.', NULL, NULL, 2.5739, 6.2, 0, 10.5225, '2026-08-19 01:49:52', '2026-11-27 20:26:40')
