VALUES (26040, 'tt0491399', NULL, 'Haze', 'ヘイズ', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/hIqlsqwfcrAxGiVaZGK3ofI18fR.jpg', 'https://image.tmdb.org/t/p/original/5RBD3JV6hs3Xl0k3Q0xx8uee43y.jpg', 'A man awakes to find himself trapped in a dirty, confined crawlspace. He barely has enough room to move. He also has no memory of why he''s there, or why he''s bleeding from a stomach wound. Apparently drugged, he occasionally ''zones out'' of his surroundings as he tries to edge towards his way to freedom. But the more he explores, the more pain he has to endure, and the more frightening his predicament becomes.', NULL, NULL, 1.4416, 6.547, 0, 6.26, '2026-09-17 03:31:35', '2026-11-27 20:26:40')
